refentry.refsect1:
&reftitle.description;
public boolnullYaf_Controller_Abstract::setViewpath stringview_directory
Définit le dossier des templates du moteur de vue lié à ce contrôleur.

&reftitle.parameters;


  view_directory


    Le dossier qui contient les templates de vue.

  &reftitle.examples;

   Exemple avec Yaf_Controller_Abstract::setViewpath


<?php
class ProductController extends Yaf_Controller_Abstract
{
    public function init() {
        // à partir de maintenant, les templates de ce contrôleur sont recherchés
        // dans application/themes/dark/views/
        $this->setViewpath(APPLICATION_PATH . "/themes/dark/views");
    }

    public function indexAction() {
        // affiche application/themes/dark/views/product/index.phtml
        $this->display("product/index.phtml");
    }
}
?>
